onClick:
{{
  (async function() {
    try {
      // 0. Récupération sécurisée du montant TTC (gestion majuscules/minuscules)
      const bl = Get_Detail_BL.data[0] || {};
      const rawTotal = bl.TOTAL_TTC ?? bl.Total_TTC ?? bl.total_ttc ?? 0;
      const totalTTC = Number(rawTotal);

      // 1. Aiguillage selon le montant réel
      if (totalTTC !== 0) {
        // ➔ Facture payante (> 0) OU Avoir (< 0) : PENNYLANE
        await Demander_Facture.run();
        showAlert('Génération de la facture/avoir Pennylane lancée...', 'info');
      } else {
        // ➔ Strictement 0 € : WORKFLOW INTERNE 0 €
        await Webhook_BL_Zero.run();
        showAlert('Génération du document 0 € lancée...', 'info');
      }

      closeModal('Modal_generer_facture');

      let tentatives = 0;
      const maxTentatives = 30;

      const interval = setInterval(async () => {
        tentatives++;

        const res = await Get_Detail_BL.run();
        const blData = res[0] || Get_Detail_BL.data[0];

        if (blData && blData.Statut_Facturation === 'Facturé') {
          clearInterval(interval);
          showAlert('Document généré avec succès !', 'success');
          navigateTo('Détail Facture', { id: blData.ID_BL });
        } else if (tentatives >= maxTentatives) {
          clearInterval(interval);
          showAlert('La génération prend plus de temps que prévu...', 'warning');
        }
      }, 1000);
    } catch (err) {
      showAlert('Erreur lors du lancement de la facturation', 'error');
      console.error(err);
    }
  })()
}}
